class Accumulator with Handler<int, int> {
  int _value;
  Accumulator([int initialValue = 0]): _value = initialValue;
  int handle(int n) => _value += n;
}

main() async {
  final actor = Actor.create(() => Accumulator(6));
  print(await actor.send(5)); // 11
  await actor.close();
}
